import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.C_fNVUec.js";const c=JSON.parse('{"title":"Quick start","description":"","frontmatter":{},"headers":[],"relativePath":"docs/quick-start.md","filePath":"docs/quick-start.md","lastUpdated":1793898059000}'),n={name:"docs/quick-start.md"};function h(p,a,o,l,d,r){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>Your first five minutes with ORC: start it, create a project, add a task and a memory, open the dashboard and connect a coding agent.</p><p>Install ORC first: <a href="./install">Install</a>.</p><h2 id="_1-start-orc" tabindex="-1">1. Start ORC <a class="header-anchor" href="#_1-start-orc" aria-label="Permalink to &quot;1. Start ORC&quot;">​</a></h2><p>Desktop app: launch it. The daemon starts and the dashboard opens. Skip to step 2.</p><p>CLI install:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>This runs in the foreground: the REST API and dashboard on <code>http://127.0.0.1:7700</code>, the job scheduler, session watchers, the gateway and the task loop. Leave it running and use a second terminal, or register it as a service with <code>orc daemon install</code>.</p><p>Check it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>The database is created on first run at <code>~/.orc/orc.db</code>.</p><h2 id="_2-create-a-project" tabindex="-1">2. Create a project <a class="header-anchor" href="#_2-create-a-project" aria-label="Permalink to &quot;2. Create a project&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My application&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>The first project you add becomes the active project. Task, memory, job and knowledge commands default to the active project. Override with <code>-p &lt;name&gt;</code>.</p><h2 id="_3-add-a-task" tabindex="-1">3. Add a task <a class="header-anchor" href="#_3-add-a-task" aria-label="Permalink to &quot;3. Add a task&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Fix the auth bug&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --priority</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> high</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>Priorities: <code>low</code>, <code>normal</code>, <code>high</code>, <code>critical</code>. The normal path is <code>todo → queued → doing → review → done</code>; a task can also be <code>changes_requested</code>, <code>blocked</code>, <code>paused</code> or <code>cancelled</code>.</p><p>To have an agent pick tasks up automatically, enable the task loop (off by default):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ORC_AGENT_LOOP_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Check which agents can run on this machine:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>See <a href="./task-flows">Task flows</a> for what happens after a task is picked up.</p><h2 id="_4-add-a-memory" tabindex="-1">4. Add a memory <a class="header-anchor" href="#_4-add-a-memory" aria-label="Permalink to &quot;4. Add a memory&quot;">​</a></h2><p>Memories are short project facts that agents load into context at session start.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> token-refresh-lock</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Check before touching token refresh&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Use RWMutex for token refresh&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --priority</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p><code>-d</code> (description) and <code>-c</code> (content) are required. <code>--priority</code> is 0-100; higher loads first. Longer procedures belong in a <a href="./skills">skill</a>.</p><h2 id="_5-add-a-job-optional" tabindex="-1">5. Add a job (optional) <a class="header-anchor" href="#_5-add-a-job-optional" aria-label="Permalink to &quot;5. Add a job (optional)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> job</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --command</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bun run test&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trigger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cron</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cron</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0 22 * * *&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> job</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nightly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span></span></code></pre></div><p>New jobs are disabled unless you pass <code>--enable</code>.</p><h2 id="_6-open-the-dashboard" tabindex="-1">6. Open the dashboard <a class="header-anchor" href="#_6-open-the-dashboard" aria-label="Permalink to &quot;6. Open the dashboard&quot;">​</a></h2><p>Open <a href="http://localhost:7700" target="_blank" rel="noreferrer">http://localhost:7700</a>. The desktop app shows the same dashboard in its window.</p><p>If an API secret is configured, the dashboard asks for it once and keeps a signed session cookie (30 days by default).</p><p>Tour of every page: <a href="./desktop-and-web">Desktop app and web dashboard</a>.</p><h2 id="_7-connect-an-agent" tabindex="-1">7. Connect an agent <a class="header-anchor" href="#_7-connect-an-agent" aria-label="Permalink to &quot;7. Connect an agent&quot;">​</a></h2><p>Register ORC&#39;s MCP server in your agent. For Claude Code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:7700/mcp</span></span></code></pre></div><p>With an API secret, add <code>--header &#39;Authorization: Bearer \${ORC_API_SECRET}&#39;</code> and export <code>ORC_API_SECRET</code> in the agent&#39;s environment.</p><p>The dashboard builds this snippet for Claude Code, Codex and other clients under <strong>Settings → MCP</strong>.</p><p>Then ask the agent to call ORC&#39;s <code>context</code> tool for <code>my-app</code>. It should return your task and memory.</p><p>Claude Code and Codex sessions appear under <strong>Sessions</strong> without further setup.</p><p>Full instructions per agent: <a href="./connect-agents">Connect agents</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./concepts">Concepts</a></li><li><a href="./cli">CLI reference</a></li><li><a href="./configuration">Configuration</a></li><li><a href="./usage-guide">Usage guide</a></li></ul>`,43)])])}const F=s(n,[["render",h]]);export{c as __pageData,F as default};
